/// Raven `strcpy(dest, src)` into a fixed-size `[c_char; N]` field — copies
/// bytes up to (and including) the NUL or the buffer capacity, whichever is
/// first (Raven's `strcpy` itself has no bound, but every call site here
/// copies a caller string into a `MAX_QPATH`-sized field, so this stays
/// faithful without reproducing the C overrun).
unsafe fn strcpy_buf<const N: usize>(dest: &mut [c_char; N], src: *const c_char) {
    let mut i = 0usize;
    while i < N - 1 {
        let c = *src.add(i);
        dest[i] = c;
        if c == 0 {
            return;
        }
        i += 1;
    }
    dest[N - 1] = 0;
}

/// Raven `AddRemap`. `remapCount`/`remappedShaders` reached via
/// `ctx.world.globals` (fork ruling 1; backfilled from the `()` placeholder —
/// see `RemappedShaders` in `game_globals.rs`).
///
/// Source: `oracle/oracle/codemp/game/g_utils.c:20-37`
pub fn AddRemap(
    ctx: GameContext<'_>,
    oldShader: *const c_char,
    newShader: *const c_char,
    timeOffset: f32,
) {
    unsafe {
        let world = &mut *ctx.world;
        for i in 0..world.globals.remapCount as usize {
            let existing = world.globals.remappedShaders.0[i].oldShader.as_ptr();
            if Q_stricmp(oldShader, existing) == 0 {
                strcpy_buf(
                    &mut world.globals.remappedShaders.0[i].newShader,
                    newShader,
                );
                world.globals.remappedShaders.0[i].timeOffset = timeOffset;
                return;
            }
        }
        if (world.globals.remapCount as usize) < MAX_SHADER_REMAPS {
            let i = world.globals.remapCount as usize;
            strcpy_buf(&mut world.globals.remappedShaders.0[i].newShader, newShader);
            strcpy_buf(&mut world.globals.remappedShaders.0[i].oldShader, oldShader);
            world.globals.remappedShaders.0[i].timeOffset = timeOffset;
            world.globals.remapCount += 1;
        }
    }
}

