/// Raven `G_TeamCommand`.
///
/// Source: `oracle/oracle/codemp/game/g_utils.c:197-207`
pub fn G_TeamCommand(
    ctx: GameContext<'_>,
    team: team_t,
    cmd: *mut c_char,
) {
    use crate::client::client_connected::CON_CONNECTED;

    unsafe {
        let world = &*ctx.world;
        let text = CStr::from_ptr(cmd).to_string_lossy().into_owned();
        for i in 0..world.level.maxclients {
            let client = &world.clients[i as usize];
            if client.pers.connected == CON_CONNECTED && client.sess.sessionTeam == team {
                trap::SendServerCommand(
                    ctx.engine,
                    GSendServerCommandArgs::new(i, CString::new(text.clone()).unwrap()),
                );
            }
        }
    }
}

/// Raven `G_Find`.
///
/// Source: `oracle/oracle/codemp/game/g_utils.c:222-243`
pub fn G_Find(
    ctx: GameContext<'_>,
    from: *mut gentity_t,
    fieldofs: c_int,
    r#match: *const c_char,
) -> *mut gentity_t {
    unsafe {
        let world = &mut *ctx.world;
        let base = world.entities.as_mut_ptr();
        let num_entities = world.level.num_entities;

        let mut cur = if from.is_null() {
            base
        } else {
            from.add(1)
        };

        while cur < base.add(num_entities as usize) {
            if (*cur).inuse != qfalse {
                let s = *((cur as *mut u8).add(fieldofs as usize) as *mut *mut c_char);
                if !s.is_null() && Q_stricmp(s, r#match) == 0 {
                    return cur;
                }
            }
            cur = cur.add(1);
        }

        core::ptr::null_mut()
    }
}

/// Raven `G_RadiusList`.
///
/// Source: `oracle/oracle/codemp/game/g_utils.c:252-311`
pub fn G_RadiusList(
    ctx: GameContext<'_>,
    origin: vec3_t,
    radius: f32,
    ignore: *mut gentity_t,
    takeDamage: qboolean,
    ent_list: *mut *mut gentity_t,
) -> c_int {
    let radius = if radius < 1.0 { 1.0 } else { radius };

    let mut mins = [0.0f32; 3];
    let mut maxs = [0.0f32; 3];
    for i in 0..3 {
        mins[i] = origin[i] - radius;
        maxs[i] = origin[i] + radius;
    }

    unsafe {
        const MAX_GENTITIES_LOCAL: usize = mp_qshared::shared::MAX_GENTITIES;
        let mut entity_list = [0 as c_int; MAX_GENTITIES_LOCAL];
        let num_listed_entities = trap::EntitiesInBox(
            ctx.engine,
            GEntitiesInBoxArgs::new(
                mins.as_ptr() as *const vec3_t,
                maxs.as_ptr() as *const vec3_t,
                entity_list.as_mut_ptr(),
                MAX_GENTITIES_LOCAL as c_int,
            ),
        );

        let world = &mut *ctx.world;
        let mut ent_count: c_int = 0;
        for e in 0..num_listed_entities {
            let ent = &mut world.entities[entity_list[e as usize] as usize] as *mut gentity_t;

            if ent == ignore || (*ent).inuse == qfalse || (*ent).takedamage != takeDamage {
                continue;
            }

            let mut v = [0.0f32; 3];
            for i in 0..3 {
                if origin[i] < (*ent).r.absmin[i] {
                    v[i] = (*ent).r.absmin[i] - origin[i];
                } else if origin[i] > (*ent).r.absmax[i] {
                    v[i] = origin[i] - (*ent).r.absmax[i];
                } else {
                    v[i] = 0.0;
                }
            }

            let dist = VectorLength(v);
            if dist >= radius {
                continue;
            }

            *ent_list.add(ent_count as usize) = ent;
            ent_count += 1;
        }

        ent_count
    }
}

/// Raven `G_Throw`. `targ->client` reached via the house
/// `(*ent).client as *mut gclient_t` cast (see `g_combat.rs`/`g_items.rs`).
///
/// Source: `oracle/oracle/codemp/game/g_utils.c:315-370`
pub fn G_Throw(
    ctx: GameContext<'_>,
    targ: *mut gentity_t,
    newDir: vec3_t,
    push: f32,
) {
    unsafe {
        let world = &mut *ctx.world;

        let mass = if (*targ).physicsBounce > 0.0 {
            (*targ).physicsBounce
        } else {
            200.0
        };

        let g_gravity = world.cvars.g_gravity.value;
        let g_knockback = world.cvars.g_knockback.value;

        let mut kvel = [0.0f32; 3];
        if g_gravity > 0.0 {
            for i in 0..3 {
                kvel[i] = newDir[i] * (g_knockback * push / mass * 0.8);
            }
            kvel[2] = newDir[2] * g_knockback * push / mass * 1.5;
        } else {
            for i in 0..3 {
                kvel[i] = newDir[i] * (g_knockback * push / mass);
            }
        }

        if !(*targ).client.is_null() {
            let client = (*targ).client as *mut gclient_t;
            for i in 0..3 {
                (*client).ps.velocity[i] += kvel[i];
            }
        } else if (*targ).s.pos.trType != trType_t::TR_STATIONARY
            && (*targ).s.pos.trType != trType_t::TR_LINEAR_STOP
            && (*targ).s.pos.trType != trType_t::TR_NONLINEAR_STOP
        {
            for i in 0..3 {
                (*targ).s.pos.trDelta[i] += kvel[i];
            }
            (*targ).s.pos.trBase = (*targ).r.currentOrigin;
            (*targ).s.pos.trTime = world.level.time;
        }

        // set the timer so that the other client can't cancel
        // out the movement immediately
        if !(*targ).client.is_null() {
            let client = (*targ).client as *mut gclient_t;
            if (*client).ps.pm_time == 0 {
                let mut t = (push * 2.0) as c_int;
                if t < 50 {
                    t = 50;
                }
                if t > 200 {
                    t = 200;
                }
                (*client).ps.pm_time = t;
                (*client).ps.pm_flags |= PMF_TIME_KNOCKBACK;
            }
        }
    }
}

