/// Raven `G_CreateFakeClient`. `gClPtrs[]` reached via `ctx.world.globals`
/// (fork ruling 1; backfilled from the `()` placeholder — see `GClPtrs` in
/// `game_globals.rs`). `BG_Alloc` is itself still parked (bg-shared
/// allocator); calling it here matches the mechanical dependency chain the
/// rest of this pass follows.
///
/// Source: `oracle/oracle/codemp/game/g_utils.c:430-438`
pub fn G_CreateFakeClient(
    ctx: GameContext<'_>,
    entNum: c_int,
    cl: *mut *mut gclient_t,
) {
    unsafe {
        let world = &mut *ctx.world;
        if world.globals.gClPtrs.0[entNum as usize].is_null() {
            world.globals.gClPtrs.0[entNum as usize] =
                crate::bg_misc::BG_Alloc(core::mem::size_of::<gclient_t>() as c_int);
        }
        *cl = world.globals.gClPtrs.0[entNum as usize] as *mut gclient_t;
    }
}

/// Raven `G_CleanAllFakeClients`.
///
/// Source: `oracle/oracle/codemp/game/g_utils.c:450-465`
pub fn G_CleanAllFakeClients(ctx: GameContext<'_>) {
    unsafe {
        let world = &mut *ctx.world;
        let mut i = MAX_CLIENTS as usize;
        while i < mp_qshared::shared::MAX_GENTITIES {
            let ent = &mut world.entities[i] as *mut gentity_t;
            if (*ent).inuse != qfalse && (*ent).s.eType == ET_NPC as c_int && !(*ent).client.is_null()
            {
                G_FreeFakeClient(&mut (*ent).client as *mut *mut c_void as *mut *mut gclient_t);
            }
            i += 1;
        }
    }
}

