/// Raven `G_MuteSound`.
///
/// Source: `oracle/oracle/codemp/game/g_utils.c:1322-1338`
pub fn G_MuteSound(
    ctx: GameContext<'_>,
    entnum: c_int,
    channel: c_int,
) {
    unsafe {
        let te = G_TempEntity(ctx, vec3_origin, EV_MUTE_SOUND as c_int);
        (*te).r.svFlags = SVF_BROADCAST;
        (*te).s.trickedentindex2 = entnum;
        (*te).s.trickedentindex = channel;

        let world = &mut *ctx.world;
        let e = &mut world.entities[entnum as usize] as *mut gentity_t;
        if (*e).s.eFlags & EF_SOUNDTRACKER != 0 {
            G_FreeEntity(ctx, e);
            (*e).s.eFlags = 0;
        }
    }
}

/// Raven `G_Sound`. `ent->client` reached via the house
/// `(*ent).client as *mut gclient_t` cast.
///
/// Source: `oracle/oracle/codemp/game/g_utils.c:1345-1372`
pub fn G_Sound(
    ctx: GameContext<'_>,
    ent: *mut gentity_t,
    channel: c_int,
    soundIndex: c_int,
) {
    debug_assert!(soundIndex != 0);

    unsafe {
        let te = G_SoundTempEntity(ctx, (*ent).r.currentOrigin, EV_GENERAL_SOUND as c_int, channel);
        (*te).s.eventParm = soundIndex;
        (*te).s.saberEntityNum = channel;

        if !ent.is_null() && !(*ent).client.is_null() && channel > trackchan_t::TRACK_CHANNEL_NONE as c_int {
            // let the client remember the index of the player entity so he
            // can kill the most recent sound on request
            let client = (*ent).client as *mut gclient_t;
            let idx = (channel - 50) as usize;
            let world = &mut *ctx.world;
            let killIdx = (*client).ps.fd.killSoundEntIndex[idx];
            if world.entities[killIdx as usize].inuse != qfalse && killIdx > MAX_CLIENTS as c_int {
                G_MuteSound(ctx, killIdx, mp_qshared::shared::sound_channel::CHAN_VOICE);
                let client = (*ent).client as *mut gclient_t;
                let killIdx = (*client).ps.fd.killSoundEntIndex[idx];
                if killIdx > MAX_CLIENTS as c_int && world.entities[killIdx as usize].inuse != qfalse {
                    let e = &mut world.entities[killIdx as usize] as *mut gentity_t;
                    G_FreeEntity(ctx, e);
                }
                (*client).ps.fd.killSoundEntIndex[idx] = 0;
            }

            (*client).ps.fd.killSoundEntIndex[idx] = (*te).s.number;
            (*te).s.trickedentindex = (*ent).s.number;
            (*te).s.eFlags = EF_SOUNDTRACKER;
        }
    }
}

/// Raven `G_SoundAtLoc`. Fork-9: `loc` is read-only (passed straight to
