/// Raven `G_ClearTrace`. Fork-9: all four vec3 params are read-only inputs
/// to `trap_Trace` (never written), so kept by-value.
///
/// Source: `oracle/oracle/codemp/game/g_utils.c:1934-1946`
pub fn G_ClearTrace(
    ctx: GameContext<'_>,
    start: vec3_t,
    mins: vec3_t,
    maxs: vec3_t,
    end: vec3_t,
    ignore: c_int,
    clipmask: c_int,
) -> qboolean {
    unsafe {
        let mut tr: trace_t = core::mem::zeroed();
        trap::Trace(
            ctx.engine,
            GTraceArgs::new(
                &mut tr as *mut trace_t,
                &start as *const vec3_t,
                &mins as *const vec3_t,
                &maxs as *const vec3_t,
                &end as *const vec3_t,
                ignore,
                clipmask,
            ),
        );

        if tr.allsolid != 0 || tr.startsolid != 0 || tr.fraction < 1.0 {
            return qfalse;
        }

        qtrue
    }
}

